"use client"

import { type ReactNode } from "react"
import { cn } from "@/lib/utils"

const EMPTY_STATE_VARIANTS = {
  /** No frame and no line — centered content on the white card surface (Figma Style=default). */
  default: "rounded-xl bg-card",
  outline: "rounded-xl border border-border bg-card",
  dashed: "rounded-xl border border-dashed border-border bg-card",
  background: "rounded-2xl bg-muted/60",
} as const

function EmptyState({
  icon,
  title,
  description,
  action,
  variant = "dashed",
  className,
}: {
  icon?: ReactNode
  title: string
  description?: string
  action?: ReactNode
  /** Frame style — mirrors the Figma Empty State "Style" variants. */
  variant?: keyof typeof EMPTY_STATE_VARIANTS
  className?: string
}) {
  return (
    <div data-slot="empty-state" className={cn("flex flex-col items-center justify-center gap-3 p-10 text-center", EMPTY_STATE_VARIANTS[variant], className)}>
      {icon && (
        <div className="grid size-12 place-items-center rounded-full bg-muted text-text-secondary [&_svg]:size-6">
          {icon}
        </div>
      )}
      <div>
        <p className="text-sm font-semibold text-foreground">{title}</p>
        {description && <p className="mt-1 text-sm text-text-secondary">{description}</p>}
      </div>
      {action}
    </div>
  )
}

export { EmptyState }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})
